// Campaign "The Lost Crown": five quests as DATA (goals §7).
//
// What lives here:
//   - metadata the SERVER needs (durations, gag ids) -> it picks gags and times phases from these;
//   - the beat scripts the TV plays (see shared/cutscene-ops.js for the op contract).
//
// STATUS: every quest has all 4 fail gags + a success ending, and they all validate and play.
// The beats below are generated by `scaffold()` from the per-gag hints (placeholder choreography:
// captions, camera, a team animation, FX, freeze-frame, reaction shot). Hand-authored choreography
// replaces it per segment or per gag: add `beats: { setup: [...], fail: { sweater: [...] } }` to a quest entry.
// The whole team succeeds or fails together: every outcome segment shows the team acting as one (team:all), never
// one player as the hero or the culprit. See docs/CUTSCENES.md for the authoring guide.
import { validateQuestScripts } from './cutscene-ops.js';
import { bridgeBeats } from './cutscenes/bridge.js';
import { woodsBeats, woodsSceneIds } from './cutscenes/woods.js';
import { vaultBeats, vaultSceneIds } from './cutscenes/vault.js';
import { dragonBeats, dragonSceneIds } from './cutscenes/dragon.js';
import { throneBeats, throneSceneIds } from './cutscenes/throne.js';

// Hand-authored choreography per quest id: (questMeta) => beats. Quests without an entry play the scaffold.
const AUTHORED = { bridge: bridgeBeats, woods: woodsBeats, vault: vaultBeats, dragon: dragonBeats, throne: throneBeats };
const SCENE_IDS = { woods: woodsSceneIds, vault: vaultSceneIds, dragon: dragonSceneIds, throne: throneSceneIds };

const SEGMENT_DEFAULTS = { setup: 5, approach: 7, moment: 3, success: 5 };

/** Placeholder choreography builder. Marks used: start, mid, goal, spot (every scene defines them). */
function scaffold(q) {
  const beats = {
    setup: [
      { t: 0, op: 'camera', shot: 'wide', dur: 5 },
      { t: 0.2, op: "caption", text: "{intro}", dur: 4.3 },
      { t: 0.4, op: 'formation', name: 'line', center: 'start', facing: 0, spacing: 2.2, walk: true, dur: 3.6 },
      { t: 3.8, op: 'banner', who: 'team:all', dur: 1.2 },
    ],
    approach: [
      { t: 0, op: 'camera', shot: 'follow', target: 'lead', dur: 7, dist: 7 },
      { t: 0.3, op: 'caption', text: q.approach, dur: 4 },
      { t: 0.3, op: 'formation', name: 'column', center: 'mid', walk: true, dur: 6.4 },
    ],
    moment: [
      { t: 0, op: 'music', track: 'stop' },
      { t: 0.1, op: 'sfx', name: 'stinger' },
      { t: 0.1, op: 'camera', shot: 'pushIn', target: 'lead', dur: 2.8 },
      { t: 0.3, op: 'caption', text: q.moment, dur: 2.4 },
      { t: 0.5, op: 'play', who: 'team:all', anim: 'Idle', loop: true },
    ],
    success: [
      { t: 0, op: 'camera', shot: 'lowAngle', target: 'team:all', dur: 3 },
      { t: 0.1, op: 'play', who: 'team:all', anim: q.teamAnim || 'Interact' },
      { t: 0.2, op: 'sfx', name: 'fanfare' },
      { t: 0.4, op: 'caption', text: q.success, dur: 3.5 },
      { t: 0.6, op: 'fx', kind: 'sparkle', at: 'team:all', count: 24 },
      { t: 2.2, op: 'camera', shot: 'wide', dur: 2.8 },
      { t: 2.4, op: 'play', who: 'team:all', anim: 'Cheer' },
      { t: 2.6, op: 'banner', who: 'team:all', dur: 2 },
    ],
    fail: {},
  };
  for (const g of q.gags) {
    const D = g.duration;
    beats.fail[g.id] = [
      { t: 0, op: 'camera', shot: 'frame', target: 'team:all', dur: 2.5 },
      { t: 0.1, op: 'caption', text: g.caption, dur: 2.8 },
      { t: 0.2, op: 'play', who: 'team:all', anim: g.anim || 'Interact' },
      { t: 1.2, op: 'sfx', name: g.sfx || 'thud' },
      { t: 1.3, op: 'fx', kind: g.fx || 'dust', at: 'team:all', count: 18 },
      { t: 2.3, op: 'play', who: 'team:all', anim: 'Cheer' }, // oblivious pride, all together
      { t: 2.6, op: 'camera', shot: 'wide', dur: 1.4 },
      { t: 3.0, op: 'freeze', dur: 1.2 },
      { t: 4.3, op: 'caption', text: q.consequence, dur: 2 },
      { t: 4.3, op: 'camera', shot: 'shake', intensity: 0.5, dur: 1 },
      { t: 4.4, op: 'sfx', name: 'wahwah' },
      { t: 4.4, op: 'play', who: 'team:all', anim: 'Hit_B' },
      { t: Math.min(D - 1.2, 5.4), op: 'camera', shot: 'frame', target: 'team:all', dur: 1 },
    ];
  }
  return beats;
}

const gag = (id, name, caption, extra = {}) => ({ id, name, caption, duration: 8, ...extra });

